const { withAppBuildGradle } = require('expo/config-plugins');

// Keep native object paths below Ninja's Windows path limit in this monorepo.
const block = `
// Lazy Bank: short native object paths (generated by Expo plugin).
android {
    externalNativeBuild {
        cmake { buildStagingDirectory file("$rootDir/../../../.cxx") }
    }
    defaultConfig {
        externalNativeBuild {
            cmake { arguments "-DCMAKE_OBJECT_PATH_MAX=240" }
        }
    }
}
`;
module.exports = function withShortCmake(config) {
  return withAppBuildGradle(config, mod => {
    if (!mod.modResults.contents.includes('short native object paths (generated by Expo plugin)')) mod.modResults.contents += block;
    return mod;
  });
};
module.exports.gradleBlock = block;
